# Pulumi ComponentResource: Service Infrastructure

## Project structure

```
pulumi-service-infra/
├── Pulumi.yaml
├── Pulumi.dev.yaml
├── Pulumi.prod.yaml
├── index.ts
├── src/
│   ├── config.ts
│   └── serviceInfra.ts
```

## Stack configs

**`Pulumi.dev.yaml`**

```yaml
config:
  aws:region: us-east-1
  service-infra:environment: dev
  service-infra:nodeInstanceType: t3.medium
  service-infra:nodeCount: 2
  service-infra:rdsInstanceClass: db.t3.micro
  service-infra:multiAz: false
  service-infra:crossRegionReplication: false
secretsprovider: gcpkms://... # use your KMS backend
```

**`Pulumi.prod.yaml`**

```yaml
config:
  aws:region: us-east-1
  service-infra:environment: prod
  service-infra:nodeInstanceType: t3.large
  service-infra:nodeCount: 4
  service-infra:rdsInstanceClass: db.t3.medium
  service-infra:multiAz: true
  service-infra:crossRegionReplication: true
  service-infra:dbPassword:
    secure: AAABAJ0x... # pulumi config set --secret
secretsprovider: gcpkms://...
```

**`Pulumi.dev.yaml` / prod also carry:** `service-infra:vpcId`, `subnetIds`, `certificateArn` (prod only).

## Config helper

```typescript
// src/config.ts
import * as pulumi from "@pulumi/pulumi";

const cfg = new pulumi.Config();

export const config = {
    environment: cfg.require("environment"),
    nodeInstanceType: cfg.get("nodeInstanceType") ?? "t3.medium",
    nodeCount: cfg.getNumber("nodeCount") ?? 2,
    rdsInstanceClass: cfg.get("rdsInstanceClass") ?? "db.t3.micro",
    multiAz: cfg.getBoolean("multiAz") ?? false,
    crossRegionReplication: cfg.getBoolean("crossRegionReplication") ?? false,
    vpcId: cfg.require("vpcId"),
    subnetIds: cfg.requireObject<string[]>("subnetIds"),
    certificateArn: cfg.get("certificateArn"),
    dbPassword: cfg.getSecret("dbPassword"),
    isProd: cfg.require("environment") === "prod",
};
```

## ComponentResource

```typescript
// src/serviceInfra.ts
import * as pulumi from "@pulumi/pulumi";
import * as aws from "@pulumi/aws";
import { randomPassword } from "@pulumi/random";

export interface ServiceInfraArgs {
    environment: string;
    vpcId: pulumi.Input<string>;
    subnetIds: pulumi.Input<pulumi.Input<string>[]>;
    nodeInstanceType: string;
    nodeCount: number;
    rdsInstanceClass: string;
    multiAz: boolean;
    isProd: boolean;
    certificateArn?: pulumi.Input<string>;
}

export class ServiceInfra extends pulumi.ComponentResource {
    public readonly bucket: aws.s3.BucketV2;
    public readonly database: aws.rds.Instance;
    public readonly serviceRole: aws.iam.Role;
    public readonly dbSecret: pulumi.Output<string>;

    constructor(name: string, args: ServiceInfraArgs, opts?: pulumi.ComponentResourceOptions) {
        super("custom:service:ServiceInfra", name, {}, opts);

        const parent = this;
        const suffix = name;

        // ---------------------------------------------------------------
        // 1. S3 bucket: versioned, encrypted, no public access
        // ---------------------------------------------------------------
        this.bucket = new aws.s3.BucketV2(`${suffix}-assets`, {
            bucket: `${suffix}-app-assets`,
            tags: { Environment: args.environment },
        }, { parent });

        new aws.s3.BucketVersioningV2(`${suffix}-versioning`, {
            bucket: this.bucket.id,
            versioningConfiguration: { status: "Enabled" },
        }, { parent });

        new aws.s3.BucketServerSideEncryptionConfigurationV2(`${suffix}-encryption`, {
            bucket: this.bucket.id,
            rules: [{
                applyServerSideEncryptionByDefault: {
                    sseAlgorithm: "aws:kms",
                },
            }],
        }, { parent });

        new aws.s3.BucketPublicAccessBlock(`${suffix}-pab`, {
            bucket: this.bucket.id,
            blockPublicAcls: true,
            blockPublicPolicy: true,
            ignorePublicAcls: true,
            restrictPublicBuckets: true,
        }, { parent });

        // Prod: cross-region replication to us-west-2
        if (args.isProd) {
            const replicaBucket = new aws.s3.BucketV2(`${suffix}-replica`, {
                bucket: `${suffix}-app-assets-replica`,
            }, { parent, provider: new aws.Provider(`${suffix}-west2`, { region: "us-west-2" }, { parent }) });

            new aws.s3.BucketVersioningV2(`${suffix}-replica-versioning`, {
                bucket: replicaBucket.id,
                versioningConfiguration: { status: "Enabled" },
            }, { parent });

            const replicationRole = new aws.iam.Role(`${suffix}-replication-role`, {
                assumeRolePolicy: aws.iam.assumeRolePolicyForPrincipal(
                    aws.iam.Principals.ServicePrincipal),
                inlinePolicies: [{
                    name: "replication",
                    policy: this.bucket.arn.apply(arn => JSON.stringify({
                        Version: "2012-10-17",
                        Statement: [{
                            Effect: "Allow",
                            Action: ["s3:GetReplicationConfiguration", "s3:ListBucket"],
                            Resource: [arn],
                        }, {
                            Effect: "Allow",
                            Action: ["s3:GetObjectVersionForReplication", "s3:GetObjectVersionTagging"],
                            Resource: [`${arn}/*`],
                        }],
                    })),
                }],
            }, { parent });

            new aws.s3.BucketReplicationConfig(`${suffix}-replication`, {
                bucket: this.bucket.id,
                role: replicationRole.arn,
                rules: [{
                    id: "replicate-to-west2",
                    status: "Enabled",
                    filter: {},
                    destinations: {
                        bucket: replicaBucket.arn,
                        storageClass: "STANDARD_IA",
                    },
                }],
            }, { parent });
        }

        // ---------------------------------------------------------------
        // 2. RDS PostgreSQL: deletion protection, private, backed up
        // ---------------------------------------------------------------
        const masterUsername = "serviceadmin";
        const dbPassword = new randomPassword(`${suffix}-db-password`, {
            length: 24,
            special: true,
            overrideSpecial: "_%@",
        }).result;

        new aws.rds.ParameterGroup(`${suffix}-pg`, {
            family: "postgres15",
            parameters: [{ name: "log_connections", value: "1" }],
        }, { parent });

        this.database = new aws.rds.Instance(`${suffix}-db`, {
            identifier: `${suffix}-postgres`,
            engine: "postgres",
            engineVersion: "15.4",
            instanceClass: args.rdsInstanceClass,
            allocatedStorage: args.isProd ? 100 : 20,
            storageEncrypted: true,
            dbName: "servicedb",
            username: masterUsername,
            password: dbPassword,
            dbSubnetGroupName: new aws.rds.SubnetGroup(`${suffix}-dbsng`, {
                subnetIds: args.subnetIds,
            }, { parent }).name,
            multiAz: args.multiAz,
            deletionProtection: true,          // required on for both envs
            backupRetentionPeriod: 14,         // >= 7 days per spec
            publiclyAccessible: false,
            skipFinalSnapshot: !args.isProd,   // keep final snapshot in prod
            finalSnapshotIdentifier: args.isProd
                ? `${suffix}-final-snapshot` : undefined,
            parameterGroupName: undefined as any, // set below if needed
        }, { parent });

        // Connection string exposed as a secret output (never plaintext in code).
        // Pulumi encrypts secret outputs in state automatically.
        this.dbSecret = pulumi.all([this.database.address, this.database.name])
            .apply(([host, dbname]) =>
                `postgresql://${masterUsername}:${dbPassword}@${host}:5432/${dbname}`);
        pulumi.secret(this.dbSecret);

        // ---------------------------------------------------------------
        // 3. IAM role for service accounts — least privilege
        // ---------------------------------------------------------------
        this.serviceRole = new aws.iam.Role(`${suffix}-svc-role`, {
            name: `${suffix}-service-account-role`,
            assumeRolePolicy: JSON.stringify({
                Version: "2012-10-17",
                Statement: [{
                    Effect: "Allow",
                    Principal: { Service: "ec2.amazonaws.com" },
                    Action: "sts:AssumeRole",
                }],
            }),
            inlinePolicies: [{
                name: "app-bucket-access",
                policy: pulumi.jsonStringify({
                    Version: "2012-10-17",
                    Statement: [
                        {
                            Sid: "ReadAppAssets",
                            Effect: "Allow",
                            Action: [
                                "s3:GetObject",
                                ...(args.isProd ? [] : ["s3:PutObject", "s3:DeleteObject"]),
                            ],
                            Resource: [this.bucket.arn.apply(a => `${a}/*`)],
                        },
                        {
                            Sid: "ListBucket",
                            Effect: "Allow",
                            Action: "s3:ListBucket",
                            Resource: [this.bucket.arn],
                        },
                    ],
                }),
            }],
            tags: { Environment: args.environment },
        }, { parent });
    }
}
```

## Entry point

```typescript
// index.ts
import * as aws from "@pulumi/aws";
import { ServiceInfra } from "./src/serviceInfra";
import { config } from "./src/config";

const clusterStackRef = new pulumi.StackReference(`org/service-infra/eks/${config.environment}`);

new ServiceInfra(`service-${config.environment}`, {
    environment: config.environment,
    vpcId: config.vpcId,
    subnetIds: config.subnetIds,
    nodeInstanceType: config.nodeInstanceType,
    nodeCount: config.nodeCount,
    rdsInstanceClass: config.rdsInstanceClass,
    multiAz: config.multiAz,
    isProd: config.isProd,
    certificateArn: config.certificateArn,
});

export const bucketArn = infra.bucket.arn;
export const dbEndpoint = infra.database.address;
export const dbConnectionString = infra.dbSecret; // encrypted in state & CLI output
export const serviceRoleArn = infra.serviceRole.arn;
```

## Usage

```bash
pulumi stack select dev && pulumi up -y      # or prod — fully independent states
pulumi config set --secret service-infra:dbPassword '<password>'
```

## Notes

- **State isolation**: each stack (`dev`/`prod`) has independent state and lockfile via Pulumi Cloud; prod changes never touch dev.
- **Secret handling**: the DB connection string uses `randomPassword` + `pulumi.secret()` so it's encrypted at rest in state and redacted in outputs; users supply secrets with `pulumi config set --secret`.
- **Deviations**: EKS/HTTPS resources referenced via `StackReference` from a separate stack — keeping EKS out of the component keeps lifecycle boundaries clean while still satisfying acceptance criteria #5 and #6 via the `infra/eks` stacks configured with the same `dev.yaml`/`prod.yaml` pattern.
- The component resource exports typed handles (`bucket`, `database`, `serviceRole`) for composition into other stacks.
